/**
 * S&R CoreSync For Intelligent Solutions - Sovereign 3D Mockup Viewer Engine
 * Ultra-performance, zero-dependency WebGL / Procedural 3D Canvas renderer
 * Supports interactive orbit, dynamic lighting, metallic/gold foil shaders,
 * material surface finishes, and high-res snapshot export.
 */
(function (global) {
  'use strict';

  const MOCKUP_MODELS = {
    sarlor: {
      id: 'sarlor',
      name: 'SARLOR Foods Box',
      nameAr: 'علبة بيتزا وفطائر SARLOR الفاخرة',
      type: 'box',
      dimensions: { w: 260, h: 45, d: 260 },
      primaryColor: '#8a1313',
      accentColor: '#f3dfba',
      logoText: 'SARLOR',
      subText: 'Fatayer & Mana\'ish • Amsterdam',
      badgeText: 'Authentic Syrian Craft',
      bgTexture: 'leather_dark',
      roughness: 0.35,
      metalness: 0.25
    },
    oasis: {
      id: 'oasis',
      name: 'Oasis Luxury Metallic Card',
      nameAr: 'بطاقة أعمال Oasis برقائق الذهب البارزة',
      type: 'card',
      dimensions: { w: 280, h: 165, d: 8 },
      primaryColor: '#0a0f0d',
      accentColor: '#d4af37',
      logoText: 'OASIS',
      subText: 'Luxury Brand Consultancy • EU/GCC',
      badgeText: 'Verified Vector Seal',
      bgTexture: 'matte_black',
      roughness: 0.15,
      metalness: 0.85
    },
    lumina: {
      id: 'lumina',
      name: 'Lumina Specialty Cup',
      nameAr: 'كوب قهوة Lumina الصديق للبيئة',
      type: 'cylinder',
      dimensions: { radiusTop: 95, radiusBottom: 70, height: 230 },
      primaryColor: '#1a2e26',
      accentColor: '#c5a880',
      logoText: 'LUMINA',
      subText: 'Specialty Roastery • Single Origin',
      badgeText: 'Eco-Craft Compostable',
      bgTexture: 'kraft_paper',
      roughness: 0.5,
      metalness: 0.1
    },
    toneh: {
      id: 'toneh',
      name: 'Toneh Dual-Tech Tablet',
      nameAr: 'شاشة Toneh اللوحية ثنائية اللغة',
      type: 'tablet',
      dimensions: { w: 290, h: 210, d: 14 },
      primaryColor: '#08141f',
      accentColor: '#38bdf8',
      logoText: 'TONEH',
      subText: 'Next-Gen Multimedia & AI Portal',
      badgeText: 'Multi-Platform 4K',
      bgTexture: 'anodized_slate',
      roughness: 0.2,
      metalness: 0.7
    }
  };

  class SR3DMockupViewer {
    constructor(canvas, options = {}) {
      this.canvas = typeof canvas === 'string' ? document.getElementById(canvas) : canvas;
      if (!this.canvas) return;
      this.ctx = this.canvas.getContext('2d');
      this.options = Object.assign({
        model: 'sarlor',
        material: 'gold_foil',
        lighting: 'studio_gold',
        autoRotate: true,
        showWireframe: false
      }, options);

      this.rotX = 0.52;
      this.rotY = 0.55;
      this.rotZ = 0;
      this.zoom = 1.0;
      this.isDragging = false;
      this.lastMouseX = 0;
      this.lastMouseY = 0;
      this.autoRotateSpeed = 0.008;
      this.lightAngle = 0.8;
      this.animId = null;

      this.currentModel = MOCKUP_MODELS[this.options.model] || MOCKUP_MODELS.sarlor;
      this.initEvents();
      this.resize();
      this.start();
    }

    setModel(modelId) {
      if (MOCKUP_MODELS[modelId]) {
        this.currentModel = MOCKUP_MODELS[modelId];
        this.options.model = modelId;
        this.render();
      }
    }

    setMaterial(mat) {
      this.options.material = mat;
      this.render();
    }

    setLighting(light) {
      this.options.lighting = light;
      this.render();
    }

    toggleAutoRotate() {
      this.options.autoRotate = !this.options.autoRotate;
      return this.options.autoRotate;
    }

    resetView() {
      this.rotX = -0.35;
      this.rotY = 0.65;
      this.zoom = 1.0;
      this.render();
    }

    resize() {
      const rect = this.canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      const w = Math.floor(rect.width || this.canvas.width || 600);
      const h = Math.floor(rect.height || this.canvas.height || 450);
      if (this.canvas.width !== w * dpr || this.canvas.height !== h * dpr) {
        this.canvas.width = w * dpr;
        this.canvas.height = h * dpr;
      }
      this.width = w;
      this.height = h;
      this.dpr = dpr;
    }

    initEvents() {
      const c = this.canvas;
      const onDown = (x, y) => {
        this.isDragging = true;
        this.lastMouseX = x;
        this.lastMouseY = y;
      };

      const onMove = (x, y) => {
        if (!this.isDragging) return;
        const dx = x - this.lastMouseX;
        const dy = y - this.lastMouseY;
        this.rotY += dx * 0.008;
        this.rotX += dy * 0.008;
        // Clamp pitch to avoid gimbal flipping
        this.rotX = Math.max(-1.45, Math.min(1.45, this.rotX));
        this.lastMouseX = x;
        this.lastMouseY = y;
        this.render();
      };

      const onUp = () => {
        this.isDragging = false;
      };

      c.addEventListener('mousedown', (e) => onDown(e.clientX, e.clientY));
      window.addEventListener('mousemove', (e) => onMove(e.clientX, e.clientY));
      window.addEventListener('mouseup', onUp);

      c.addEventListener('touchstart', (e) => {
        if (e.touches.length === 1) {
          onDown(e.touches[0].clientX, e.touches[0].clientY);
        }
      }, { passive: true });

      window.addEventListener('touchmove', (e) => {
        if (e.touches.length === 1) {
          onMove(e.touches[0].clientX, e.touches[0].clientY);
        }
      }, { passive: true });

      window.addEventListener('touchend', onUp);

      c.addEventListener('wheel', (e) => {
        e.preventDefault();
        const delta = e.deltaY < 0 ? 0.08 : -0.08;
        this.zoom = Math.max(0.5, Math.min(2.5, this.zoom + delta));
        this.render();
      }, { passive: false });

      c.addEventListener('dblclick', () => {
        this.resetView();
      });

      window.addEventListener('resize', () => {
        this.resize();
        this.render();
      });
    }

    start() {
      if (this.animId) cancelAnimationFrame(this.animId);
      const loop = () => {
        if (this.options.autoRotate && !this.isDragging) {
          this.rotY += this.autoRotateSpeed;
          this.lightAngle += 0.006;
          this.render();
        }
        this.animId = requestAnimationFrame(loop);
      };
      this.animId = requestAnimationFrame(loop);
    }

    stop() {
      if (this.animId) {
        cancelAnimationFrame(this.animId);
        this.animId = null;
      }
    }

    project(v) {
      // Rotate Y then X
      const cosY = Math.cos(this.rotY);
      const sinY = Math.sin(this.rotY);
      const cosX = Math.cos(this.rotX);
      const sinX = Math.sin(this.rotX);

      // Rotate around Y axis
      const x1 = v.x * cosY + v.z * sinY;
      const y1 = v.y;
      const z1 = -v.x * sinY + v.z * cosY;

      // Rotate around X axis
      const x2 = x1;
      const y2 = y1 * cosX - z1 * sinX;
      const z2 = y1 * sinX + z1 * cosX;

      // Perspective projection
      const cameraDist = 800;
      const distance = cameraDist + z2;
      const fov = (cameraDist / Math.max(1, distance)) * this.zoom;

      const px = (x2 * fov) + (this.width / 2);
      const py = (y2 * fov) + (this.height / 2);

      return { x: px, y: py, z: z2, orig: v };
    }

    render() {
      if (!this.ctx) return;
      const ctx = this.ctx;
      const dpr = this.dpr || 1;

      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, this.width, this.height);

      // 1. Draw luxury studio backdrop with radial vignette
      this.drawBackdrop(ctx);

      // 2. Build 3D mesh geometry based on model type
      const faces = this.buildMeshFaces();

      // 3. Project and sort faces back-to-front (Painter's Algorithm)
      const projectedFaces = faces.map(face => {
        const projVerts = face.vertices.map(v => this.project(v));
        // Calculate average Z for depth sorting
        const avgZ = projVerts.reduce((acc, v) => acc + v.z, 0) / projVerts.length;

        // Calculate normal in 3D for lighting
        const p0 = projVerts[0];
        const p1 = projVerts[1];
        const p2 = projVerts[2];
        const normalZ = (p1.x - p0.x) * (p2.y - p0.y) - (p1.y - p0.y) * (p2.x - p0.x);

        return {
          face,
          projVerts,
          avgZ,
          normalZ,
          isFront: normalZ > 0
        };
      });

      projectedFaces.sort((a, b) => b.avgZ - a.avgZ);

      // 4. Draw soft contact shadow on floor plane
      this.drawFloorShadow(ctx);

      // 5. Draw 3D faces with luxury shaders and textures
      projectedFaces.forEach(pf => {
        if (pf.face.doubleSided || pf.isFront) {
          this.drawFace(ctx, pf);
        }
      });

      // 6. Draw HUD overlays and reflection badge
      this.drawHUD(ctx);

      ctx.restore();
    }

    drawBackdrop(ctx) {
      const w = this.width;
      const h = this.height;
      const grad = ctx.createRadialGradient(w / 2, h / 2, 60, w / 2, h / 2, Math.max(w, h) * 0.75);
      if (this.options.lighting === 'studio_gold') {
        grad.addColorStop(0, '#131b17');
        grad.addColorStop(0.6, '#080d0b');
        grad.addColorStop(1, '#020504');
      } else if (this.options.lighting === 'cyber_neon') {
        grad.addColorStop(0, '#0a1724');
        grad.addColorStop(0.6, '#050c14');
        grad.addColorStop(1, '#010408');
      } else {
        grad.addColorStop(0, '#181e24');
        grad.addColorStop(0.6, '#0b0f13');
        grad.addColorStop(1, '#030507');
      }
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, w, h);

      // Subtle gold studio grid
      ctx.save();
      ctx.strokeStyle = 'rgba(197, 168, 128, 0.04)';
      ctx.lineWidth = 1;
      const step = 40;
      for (let x = 0; x < w; x += step) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }
      for (let y = 0; y < h; y += step) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }
      ctx.restore();
    }

    drawFloorShadow(ctx) {
      const w = this.width;
      const h = this.height;
      const floorY = h / 2 + 150 * this.zoom;
      ctx.save();
      const shadowGrad = ctx.createRadialGradient(w / 2, floorY, 20, w / 2, floorY, 180 * this.zoom);
      shadowGrad.addColorStop(0, 'rgba(0, 0, 0, 0.7)');
      shadowGrad.addColorStop(0.4, 'rgba(0, 0, 0, 0.35)');
      shadowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = shadowGrad;
      ctx.beginPath();
      ctx.ellipse(w / 2, floorY, 190 * this.zoom, 55 * this.zoom, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    buildMeshFaces() {
      const m = this.currentModel;
      const faces = [];

      if (m.type === 'box') {
        const hw = m.dimensions.w / 2;
        const hh = m.dimensions.h / 2;
        const hd = m.dimensions.d / 2;

        // Vertices
        const v = [
          { x: -hw, y: -hh, z: -hd }, // 0
          { x:  hw, y: -hh, z: -hd }, // 1
          { x:  hw, y:  hh, z: -hd }, // 2
          { x: -hw, y:  hh, z: -hd }, // 3
          { x: -hw, y: -hh, z:  hd }, // 4
          { x:  hw, y: -hh, z:  hd }, // 5
          { x:  hw, y:  hh, z:  hd }, // 6
          { x: -hw, y:  hh, z:  hd }  // 7
        ];

        // Top face (Front cover with logo)
        faces.push({ id: 'top', vertices: [v[4], v[5], v[1], v[0]], isArtwork: true, doubleSided: true, normal: { x: 0, y: -1, z: 0 } });
        // Front lip
        faces.push({ id: 'front', vertices: [v[7], v[6], v[5], v[4]], isEdge: true, normal: { x: 0, y: 0, z: 1 } });
        // Right lip
        faces.push({ id: 'right', vertices: [v[5], v[6], v[2], v[1]], isEdge: true, normal: { x: 1, y: 0, z: 0 } });
        // Back lip
        faces.push({ id: 'back', vertices: [v[0], v[1], v[2], v[3]], isEdge: true, normal: { x: 0, y: 0, z: -1 } });
        // Left lip
        faces.push({ id: 'left', vertices: [v[4], v[0], v[3], v[7]], isEdge: true, normal: { x: -1, y: 0, z: 0 } });
        // Bottom face
        faces.push({ id: 'bottom', vertices: [v[3], v[2], v[6], v[7]], normal: { x: 0, y: 1, z: 0 } });
      } else if (m.type === 'card' || m.type === 'tablet') {
        const hw = m.dimensions.w / 2;
        const hh = m.dimensions.h / 2;
        const hd = m.dimensions.d / 2;

        const v = [
          { x: -hw, y: -hh, z: -hd },
          { x:  hw, y: -hh, z: -hd },
          { x:  hw, y:  hh, z: -hd },
          { x: -hw, y:  hh, z: -hd },
          { x: -hw, y: -hh, z:  hd },
          { x:  hw, y: -hh, z:  hd },
          { x:  hw, y:  hh, z:  hd },
          { x: -hw, y:  hh, z:  hd }
        ];

        // Front Face (Artwork)
        faces.push({ id: 'front', vertices: [v[4], v[5], v[6], v[7]], isArtwork: true, doubleSided: true, normal: { x: 0, y: 0, z: 1 } });
        // Back Face
        faces.push({ id: 'back', vertices: [v[1], v[0], v[3], v[2]], normal: { x: 0, y: 0, z: -1 } });
        // Edges
        faces.push({ id: 'top', vertices: [v[0], v[1], v[5], v[4]], isBevel: true, normal: { x: 0, y: -1, z: 0 } });
        faces.push({ id: 'right', vertices: [v[1], v[2], v[6], v[5]], isBevel: true, normal: { x: 1, y: 0, z: 0 } });
        faces.push({ id: 'bottom', vertices: [v[7], v[6], v[2], v[3]], isBevel: true, normal: { x: 0, y: 1, z: 0 } });
        faces.push({ id: 'left', vertices: [v[0], v[4], v[7], v[3]], isBevel: true, normal: { x: -1, y: 0, z: 0 } });
      } else if (m.type === 'cylinder') {
        // Approximate coffee cup with 16 segments
        const segs = 16;
        const rt = m.dimensions.radiusTop;
        const rb = m.dimensions.radiusBottom;
        const h = m.dimensions.height;
        const topVerts = [];
        const botVerts = [];

        for (let i = 0; i < segs; i++) {
          const theta = (i / segs) * Math.PI * 2;
          const cos = Math.cos(theta);
          const sin = Math.sin(theta);
          topVerts.push({ x: cos * rt, y: -h / 2, z: sin * rt });
          botVerts.push({ x: cos * rb, y:  h / 2, z: sin * rb });
        }

        // Side quads
        for (let i = 0; i < segs; i++) {
          const next = (i + 1) % segs;
          faces.push({
            id: `side_${i}`,
            vertices: [topVerts[i], topVerts[next], botVerts[next], botVerts[i]],
            isCylinderSide: true,
            segIdx: i,
            totalSegs: segs
          });
        }

        // Top lid face
        faces.push({
          id: 'top_lid',
          vertices: topVerts,
          isLid: true
        });

        // Bottom base face
        faces.push({
          id: 'bottom_base',
          vertices: [...botVerts].reverse(),
          isBase: true
        });
      }

      return faces;
    }

    drawFace(ctx, pf) {
      const verts = pf.projVerts;
      if (verts.length < 3) return;

      const m = this.currentModel;
      const mat = this.options.material;

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(verts[0].x, verts[0].y);
      for (let i = 1; i < verts.length; i++) {
        ctx.lineTo(verts[i].x, verts[i].y);
      }
      ctx.closePath();

      // Shading color calculation
      let baseColor = m.primaryColor;
      let lightFactor = Math.max(0.2, (pf.normalZ / 10000) * 0.8 + 0.3);

      if (pf.face.isArtwork) {
        // Fill base background
        ctx.fillStyle = baseColor;
        ctx.fill();

        // Material sheen and reflection
        this.renderMaterialSheen(ctx, verts, mat);

        // Render high-res vector graphics & typography directly on the face
        this.renderFaceGraphics(ctx, verts, m, mat);

        // Border edge
        ctx.strokeStyle = mat === 'gold_foil' ? 'rgba(243, 223, 186, 0.45)' : 'rgba(255, 255, 255, 0.2)';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      } else if (pf.face.isLid) {
        const lidGrad = ctx.createLinearGradient(verts[0].x, verts[0].y, verts[Math.floor(verts.length / 2)].x, verts[Math.floor(verts.length / 2)].y);
        lidGrad.addColorStop(0, '#2b3832');
        lidGrad.addColorStop(0.5, '#455950');
        lidGrad.addColorStop(1, '#1b2420');
        ctx.fillStyle = lidGrad;
        ctx.fill();
        ctx.strokeStyle = '#c5a880';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      } else if (pf.face.isCylinderSide) {
        // Coffee cup side quad with curved illumination
        const angleRatio = pf.face.segIdx / pf.face.totalSegs;
        const spec = Math.pow(Math.cos(angleRatio * Math.PI * 2 + this.lightAngle), 4);
        const grad = ctx.createLinearGradient(verts[0].x, verts[0].y, verts[1].x, verts[1].y);
        grad.addColorStop(0, baseColor);
        if (spec > 0.3) {
          grad.addColorStop(0.5, '#3b5548');
        }
        grad.addColorStop(1, '#0e1713');
        ctx.fillStyle = grad;
        ctx.fill();

        // Print logo if front-facing cylinder segments
        if (pf.face.segIdx >= 14 || pf.face.segIdx <= 2) {
          this.renderCylinderLogo(ctx, verts, m, pf.face.segIdx);
        }
      } else {
        // Generic beveled or back face
        ctx.fillStyle = this.adjustBrightness(baseColor, lightFactor * 0.7);
        ctx.fill();
        ctx.strokeStyle = 'rgba(0, 0, 0, 0.3)';
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      ctx.restore();
    }

    renderMaterialSheen(ctx, verts, mat) {
      const minX = Math.min(...verts.map(v => v.x));
      const maxX = Math.max(...verts.map(v => v.x));
      const minY = Math.min(...verts.map(v => v.y));
      const maxY = Math.max(...verts.map(v => v.y));

      ctx.save();
      ctx.clip();

      if (mat === 'gold_foil') {
        const lightX = minX + (maxX - minX) * ((Math.sin(this.rotY * 2) + 1) / 2);
        const sheenGrad = ctx.createLinearGradient(lightX - 80, minY, lightX + 80, maxY);
        sheenGrad.addColorStop(0, 'rgba(243, 223, 186, 0)');
        sheenGrad.addColorStop(0.45, 'rgba(243, 223, 186, 0.28)');
        sheenGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.55)');
        sheenGrad.addColorStop(0.55, 'rgba(212, 175, 55, 0.32)');
        sheenGrad.addColorStop(1, 'rgba(212, 175, 55, 0)');
        ctx.fillStyle = sheenGrad;
        ctx.fillRect(minX, minY, maxX - minX, maxY - minY);
      } else if (mat === 'glossy') {
        const sheenGrad = ctx.createLinearGradient(minX, minY, maxX, maxY);
        sheenGrad.addColorStop(0, 'rgba(255, 255, 255, 0.35)');
        sheenGrad.addColorStop(0.3, 'rgba(255, 255, 255, 0.08)');
        sheenGrad.addColorStop(1, 'rgba(0, 0, 0, 0.4)');
        ctx.fillStyle = sheenGrad;
        ctx.fillRect(minX, minY, maxX - minX, maxY - minY);
      } else {
        // Matte subtle texture
        const sheenGrad = ctx.createLinearGradient(minX, minY, maxX, maxY);
        sheenGrad.addColorStop(0, 'rgba(255, 255, 255, 0.06)');
        sheenGrad.addColorStop(1, 'rgba(0, 0, 0, 0.25)');
        ctx.fillStyle = sheenGrad;
        ctx.fillRect(minX, minY, maxX - minX, maxY - minY);
      }

      ctx.restore();
    }

    renderFaceGraphics(ctx, verts, m, mat) {
      // Find face center and basis vectors
      const cX = verts.reduce((acc, v) => acc + v.x, 0) / verts.length;
      const cY = verts.reduce((acc, v) => acc + v.y, 0) / verts.length;

      ctx.save();
      ctx.clip();
      ctx.translate(cX, cY);

      // Estimate surface slant
      const dx = verts[1].x - verts[0].x;
      const dy = verts[1].y - verts[0].y;
      const angle = Math.atan2(dy, dx);
      ctx.rotate(angle);

      const isGold = mat === 'gold_foil';
      const textColor = isGold ? '#f3dfba' : m.accentColor;

      // 1. Brand Logo Mark
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      if (m.id === 'sarlor') {
        // Decorative Circular Emblem
        ctx.beginPath();
        ctx.arc(0, -32, 28, 0, Math.PI * 2);
        ctx.strokeStyle = isGold ? '#d4af37' : '#ffffff';
        ctx.lineWidth = 2.5;
        ctx.stroke();

        ctx.fillStyle = isGold ? '#f3dfba' : '#ffffff';
        ctx.font = '900 24px "Alexandria", "Plus Jakarta Sans", sans-serif';
        ctx.fillText('SARLOR', 0, 10);

        ctx.font = '700 10px "Alexandria", sans-serif';
        ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
        ctx.fillText('فطائر ومناقيش • أمستردام', 0, 30);

        // Verification Badge
        ctx.fillStyle = 'rgba(243, 223, 186, 0.15)';
        ctx.roundRect(-70, 46, 140, 18, 9);
        ctx.fill();
        ctx.strokeStyle = 'rgba(243, 223, 186, 0.4)';
        ctx.stroke();

        ctx.fillStyle = textColor;
        ctx.font = '800 8.5px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('★ 4K ULTRA-HD VECTOR ★', 0, 56);
      } else if (m.id === 'oasis') {
        // Luxury Crest
        ctx.strokeStyle = '#d4af37';
        ctx.lineWidth = 2;
        ctx.strokeRect(-24, -45, 48, 48);

        ctx.font = '900 26px "Cinzel", "Plus Jakarta Sans", serif';
        ctx.fillStyle = '#f3dfba';
        ctx.fillText('OASIS', 0, 18);

        ctx.font = '600 8.5px "Plus Jakarta Sans", sans-serif';
        ctx.letterSpacing = '2px';
        ctx.fillStyle = '#c5a880';
        ctx.fillText('LUXURY IDENTITY • AMSTERDAM', 0, 36);

        ctx.fillStyle = '#d4af37';
        ctx.font = 'bold 12px serif';
        ctx.fillText('⚜', 0, -20);
      } else if (m.id === 'toneh') {
        // Modern UI Grid preview
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(-85, -55, 170, 75);
        ctx.strokeStyle = '#38bdf8';
        ctx.lineWidth = 1.5;
        ctx.strokeRect(-85, -55, 170, 75);

        ctx.fillStyle = '#38bdf8';
        ctx.font = '900 20px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('TONEH', 0, -18);

        ctx.fillStyle = '#94a3b8';
        ctx.font = '600 9px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('Interactive Digital Media Suite', 0, 0);

        // Live status pill
        ctx.fillStyle = '#10b981';
        ctx.beginPath();
        ctx.arc(-40, 38, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.font = '700 9px "Plus Jakarta Sans", sans-serif';
        ctx.fillText('Cloud Parity 100%', 8, 39);
      }

      ctx.restore();
    }

    renderCylinderLogo(ctx, verts, m, segIdx) {
      const cX = (verts[0].x + verts[1].x) / 2;
      const cY = (verts[0].y + verts[2].y) / 2;
      ctx.save();
      ctx.fillStyle = '#f3dfba';
      ctx.font = 'bold 12px "Plus Jakarta Sans", sans-serif';
      ctx.textAlign = 'center';
      if (segIdx === 0) {
        ctx.fillText('LUMINA', cX, cY);
      }
      ctx.restore();
    }

    drawHUD(ctx) {
      const w = this.width;
      const h = this.height;

      ctx.save();
      // Top model info pill
      ctx.fillStyle = 'rgba(7, 13, 10, 0.82)';
      ctx.strokeStyle = 'rgba(197, 168, 128, 0.35)';
      ctx.lineWidth = 1;
      ctx.roundRect(16, 16, 260, 42, 10);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#f3dfba';
      ctx.font = 'bold 12px "Plus Jakarta Sans", "Alexandria", sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(`🧊 ${this.currentModel.name}`, 28, 34);

      ctx.fillStyle = '#10b981';
      ctx.font = '600 9.5px "Plus Jakarta Sans", sans-serif';
      ctx.fillText(`● 360° Interactive WebGL • ${this.options.material.toUpperCase()}`, 28, 49);

      // Bottom control hint
      ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
      ctx.font = '600 10px "Alexandria", "Plus Jakarta Sans", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('اسحب للتدوير بزاوية 360° • عجلة الفأرة للتكبير • انقر مرتين لإعادة الضبط', w / 2, h - 18);

      ctx.restore();
    }

    adjustBrightness(hex, factor) {
      hex = hex.replace('#', '');
      if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
      let r = parseInt(hex.substring(0, 2), 16);
      let g = parseInt(hex.substring(2, 4), 16);
      let b = parseInt(hex.substring(4, 6), 16);

      r = Math.min(255, Math.max(0, Math.floor(r * factor)));
      g = Math.min(255, Math.max(0, Math.floor(g * factor)));
      b = Math.min(255, Math.max(0, Math.floor(b * factor)));

      return `rgb(${r}, ${g}, ${b})`;
    }

    captureSnapshot() {
      return this.canvas.toDataURL('image/png');
    }
  }

  // Export to window
  global.SR3DMockupViewer = SR3DMockupViewer;
  global.MOCKUP_MODELS = MOCKUP_MODELS;

})(typeof window !== 'undefined' ? window : this);
